export interface ProtocolStep { n: number; action: string; doses?: string; note?: string; branch?: string; flag?: string }
export interface ProtocolRow { id: string; name: string; sp: string; trigger: string; priority: string; steps: ProtocolStep[] }
export interface LesionRow { id: string; loc: string; loc_name: string; sp: string; cat: string; sub: string; urg: string; signs: string; [k: string]: string | boolean | undefined }
export interface DiffRow { id: string; filter: string; loc: string; sp: string; order: number; name: string; feat: string; minDx: string; [k: string]: string | number | undefined }
export interface DiseaseRow { id: string; name: string; sp: string; [k: string]: string | boolean | undefined }
export interface Db {
  lesion_type: LesionRow[]
  differentials: DiffRow[]
  disease_page: DiseaseRow[]
  protocols: ProtocolRow[]
}

